// Hoisted variables used across functions
let _duplicateSet = new Set(); // origIndex values that are duplicates
let _crossSiteDupSet = new Set(); // origIndex values duplicated on ANOTHER source site
let _urlVariantSet = new Set();   // origIndex values whose rel=canonical points elsewhere
let _variantTargetMissingSet = new Set(); // ...and whose canonical target wasn't crawled

// All KKE states (built-in + custom)
const BUILTIN_KKE = ['Keep', 'Kill', 'Evolve', 'Consolidate', 'Exclude'];
const _sessionChangeLog = [];

function logChange(origIndex, field, oldValue, newValue) {
  if (oldValue === newValue) return;
  const url = state.urlColumn ? (state.editedRows[origIndex]?.[state.urlColumn] || '') : '';
  _sessionChangeLog.push({
    timestamp: new Date().toISOString(),
    row: origIndex + 1,
    url: String(url).substring(0, 200),
    field,
    from: String(oldValue || '').substring(0, 200),
    to: String(newValue || '').substring(0, 200)
  });
}
function allKkeStates() {
  return [...BUILTIN_KKE, ...state.customKkeStates.map(s => s.label)];
}

/** Label order for rendering a KKE tally: every defined state (so a state with a
 *  zero count still reports zero), then any rogue (undefined/typo) value present
 *  in the tally, sorted — same ordering rule as collectKkeValuesPresent(). */
function kkeLabelsFor(counts) {
  const defined = allKkeStates();
  const known = new Set(defined);
  const rogue = Object.keys(counts || {}).filter(k => !known.has(k)).sort();
  return [...defined, ...rogue];
}

// Column name helpers — use these instead of hardcoding audit column names
function kkeCol()   { return state.columnMap.kke; }
function tagsCol()  { return state.columnMap.tags; }
function notesCol() { return state.columnMap.notes; }
function groupCol()        { return state.columnMap.group; }
function primaryTagCol()   { return state.columnMap.primaryTag; }
function smeDecisionCol()  { return state.columnMap.smeDecision; }
function smeNotesCol()     { return state.columnMap.smeNotes; }
function contentOwnerCol() { return state.columnMap.contentOwner; }
function finalKkeCol()     { return state.columnMap.finalKke; }

/** Parses an SME_Decision cell into a normalized decision. Recognizes
 *  "Approve"/"Accept", the documented "Change: <value>" override, AND a bare
 *  status value with no prefix at all — SMEs don't reliably follow the
 *  Change: convention. The override value is never checked against the
 *  project's current KKE vocabulary (allKkeStates()); it's whatever text the
 *  SME wrote, known state or not. A bare value that just restates the row's
 *  own KKE_Recommendation (case-insensitive) counts as an implicit approval,
 *  not an override — only an explicit "Change:" is unconditionally a change. */
function parseSmeDecision(smeRaw, currentKke) {
  const sme = String(smeRaw || '').trim();
  if (!sme) return { reviewed: false, agree: false, changed: false, value: '' };
  if (/^(approve|accept)$/i.test(sme)) return { reviewed: true, agree: true, changed: false, value: '' };
  if (/^change:/i.test(sme)) {
    const value = sme.replace(/^change:\s*/i, '').trim();
    return { reviewed: true, agree: false, changed: !!value, value };
  }
  const kke = String(currentKke || '').trim();
  if (kke && sme.toLowerCase() === kke.toLowerCase()) {
    return { reviewed: true, agree: true, changed: false, value: '' };
  }
  return { reviewed: true, agree: false, changed: true, value: sme };
}

// ─── Status code utilities ────────────────────────────────────────────────────

const STATUS_CODE_LABELS = {
  301:'Moved Permanently', 302:'Found', 303:'See Other',
  307:'Temporary Redirect', 308:'Permanent Redirect',
  400:'Bad Request', 401:'Unauthorized', 403:'Forbidden',
  404:'Not Found', 405:'Method Not Allowed', 410:'Gone',
  500:'Internal Server Error', 502:'Bad Gateway',
  503:'Service Unavailable', 504:'Gateway Timeout'
};

function statusCodeCategory(code) {
  const n = parseInt(code, 10);
  if (n >= 300 && n < 400) return '3xx';
  if (n >= 400 && n < 500) return '4xx';
  if (n >= 500 && n < 600) return '5xx';
  return null;
}

// ─── Content vs non-content rows ─────────────────────────────────────────────
//
// A crawl is a list of URLs that responded, not a list of pages — and the
// headline number in a client report has to say which one it is counting. A
// stakeholder reading "~13,000 pages audited" will ask whether they are really
// migrating ~13,000 pages, and the honest answer subtracts the redirects and the
// dead URLs, which were never content in the first place.
//
// Derived from the crawl's own Status Code rather than stored, so it is right
// retroactively in every existing project and needs no decision from the user.
// A file with no Status Code column reports everything as content, which is
// exactly the pre-existing behavior.
//
// 5xx is deliberately COUNTED AS CONTENT. A 500 is a page that exists and is
// broken — Triage Non-200 defaults it to Evolve for that reason — so dropping
// it from the inventory would hide real work rather than reveal padding. Only
// 3xx (the URL is a signpost to somewhere else) and 4xx (the URL is gone) are
// non-content.
//
// This is orthogonal to KKE. Exclude is a decision a person made about scope;
// this is a fact about what the URL returned. Keeping them separate is what
// lets a report say "~6,500 content pages, of which 2,000 are being killed,
// plus ~4,100 inherited redirects" instead of blurring the two together.

/** The crawl's Status Code column, whatever case it was exported in. */
function statusCodeCol() {
  return (state.headers || []).find(h => h.toLowerCase() === 'status code') || '';
}

/** '' (content), 'redirect' (3xx) or 'gone' (4xx). `scCol` may be pre-resolved
 *  by callers looping over thousands of rows. */
function nonContentKind(row, scCol) {
  const col = scCol !== undefined ? scCol : statusCodeCol();
  if (!col) return '';
  const cat = statusCodeCategory(parseInt(row[col] || '', 10));
  if (cat === '3xx') return 'redirect';
  if (cat === '4xx') return 'gone';
  return '';
}

/** True when this URL never served a page, so it shouldn't be counted as one. */
function isNonContentRow(row, scCol) {
  return nonContentKind(row, scCol) !== '';
}

/** The crawl's own "Redirect URL" column — where a 3xx URL currently points.
 *  Screaming Frog's name; matched case-insensitively like the Status Code column. */
function redirectUrlCol() {
  return (state.headers || []).find(h => h.toLowerCase() === 'redirect url') || '';
}

/** The destination the LIVE site currently redirects this URL to, per the crawl.
 *  Only meaningful for 3xx rows; blank for everything else. */
function crawlRedirectUrl(row) {
  if (nonContentKind(row) !== 'redirect') return '';
  const col = redirectUrlCol();
  return col ? String(row[col] || '').trim() : '';
}

function defaultTriageAction(code) {
  const n = parseInt(code, 10);
  if (n >= 300 && n < 400) return 'kill-redirect';
  if (n === 404) return 'kill-404';
  if (n >= 400 && n < 500) return 'kill';
  if (n >= 500 && n < 600) return 'evolve';
  return 'skip';
}

